// (Final, Native, Static, Public, HasOutParams, BlueprintCallable)
// Parameters:
// struct FVolumePerformanceMetrics        InMetrics                                              (ConstParm, Parm, OutParm, ReferenceParm, NoDestructor, NativeAccessSpecifierPublic)
// bool                                    bOutIsOverMemoryLimit                                  (Parm, OutParm, ZeroConstructor, IsPlainOldData, NoDestructor, HasGetValueTypeHash, NativeAccessSpecifierPublic)
// bool                                    bOutIsOverMemoryMargin                                 (Parm, OutParm, ZeroConstructor, IsPlainOldData, NoDestructor, HasGetValueTypeHash, NativeAccessSpecifierPublic)

void UVolumePerformanceMetricsHelpers::CheckIfVolumeWillBeOverMemory(const struct FVolumePerformanceMetrics& InMetrics, bool* bOutIsOverMemoryLimit, bool* bOutIsOverMemoryMargin)
{
	static class UFunction* Func = nullptr;
	class UClass* StaticClss = StaticClass();

	if (Func == nullptr)
		Func = StaticClss->FindFunction("CheckIfVolumeWillBeOverMemory");

	Params::VolumePerformanceMetricsHelpers_CheckIfVolumeWillBeOverMemory Parms{};

	Parms.InMetrics = std::move(InMetrics);

	StaticClss->DefaultObject->ProcessEvent(Func, &Parms);

	if (bOutIsOverMemoryLimit != nullptr)
		*bOutIsOverMemoryLimit = Parms.bOutIsOverMemoryLimit;

	if (bOutIsOverMemoryMargin != nullptr)
		*bOutIsOverMemoryMargin = Parms.bOutIsOverMemoryMargin;
}


